sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    var insights = [];

    var gr = new GlideRecordSecure('x_2130921_caresy_0_ai_insight');
    gr.orderByDesc('generated_date');
    gr.query();

    while (gr.next()) {

        insights.push({
            sys_id: gr.getUniqueValue(),

            ai_insight_number: gr.getValue('number'),

            patient_sys_id: gr.getValue('patient'),
            patient: gr.getDisplayValue('patient'),

            admission_sys_id: gr.getValue('admission'),
            admission: gr.getDisplayValue('admission'),

            care_plan_sys_id: gr.getValue('care_plan'),
            care_plan: gr.getDisplayValue('care_plan'),

            insight_type: gr.getDisplayValue('insight_type'),
            severity: gr.getDisplayValue('severity'),

            insight_title: gr.getValue('insight_title'),
            insight: gr.getValue('insight'),
            recommendation: gr.getValue('recommendation'),

            confidence_score: gr.getValue('confidence_score'),

            generated_date: gr.getValue('generated_date'),

            insight_status: gr.getDisplayValue('insight_status'),

            reviewed_by_sys_id: gr.getValue('reviewed_by'),
            reviewed_by: gr.getDisplayValue('reviewed_by'),

            review_notes: gr.getValue('review_notes'),

            active: gr.getValue('active') == '1'
        });
    }

    response.setStatus(200);

    response.setBody({
        success: true,
        count: insights.length,
        ai_insights: insights
    });

})(request, response);
